using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;using System.Threading.Tasks;
class Setup:Form {
 static readonly string[] Formats={"3mf","stl","obj","ply","off","amf","gcode","gco","step","stp","sldprt","sldasm","slddrw","prtdot","asmdot","drwdot","eprt","easm","edrw"};
 static string[] ExistingFormats(){return Formats.Where(ext=>{int i=Array.IndexOf(Formats,ext);string id=i==0?"{B7E33521-1381-4ED2-9C3F-989B9CF937E8}":"{A37F1000-17A0-4D18-BA10-"+i.ToString("000000000000")+"}";return string.Equals(Convert.ToString(Microsoft.Win32.Registry.GetValue("HKEY_CURRENT_USER\\Software\\Classes\\."+ext+"\\shellex\\{e357fccd-a995-4576-b01f-234630154e96}","",null)),id,StringComparison.OrdinalIgnoreCase);}).ToArray();}
 static string ChooseTarget(string home,bool existing){if(!existing&&!Directory.Exists(Path.Combine(home,"App")))return Path.Combine(home,"App");var version=FileVersionInfo.GetVersionInfo(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"manager","3DSTL.dll"));return Path.Combine(home,"Versions",version.FileMajorPart+"."+version.FileMinorPart+"."+version.FileBuildPart+"-"+Guid.NewGuid().ToString("N").Substring(0,8));}

 ComboBox language=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=160};Button install=new Button{Width=180,Height=40};Label info=new Label{AutoSize=false,Width=555,Height=130};Label state=new Label{Width=555,Height=60};bool english;string source=AppDomain.CurrentDomain.BaseDirectory;
 Setup(){Text="3DSTL Setup / 安装";ClientSize=new Size(610,350);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Microsoft YaHei UI",10);var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22),FlowDirection=FlowDirection.TopDown};Controls.Add(panel);panel.Controls.Add(new Label{Text="3DSTL",Font=new Font(Font.FontFamily,24,FontStyle.Bold),Height=48,AutoSize=true});language.Items.AddRange(new object[]{"简体中文","English"});language.SelectedIndex=0;language.SelectedIndexChanged+=delegate{english=language.SelectedIndex==1;RefreshText();};panel.Controls.Add(language);panel.Controls.Add(info);panel.Controls.Add(install);panel.Controls.Add(state);install.Click+=async delegate{install.Enabled=false;try{if(!Environment.Is64BitOperatingSystem)throw new IOException(english?"Windows x64 is required.":"需要64位Windows。");string runtime=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"dotnet","shared","Microsoft.WindowsDesktop.App");if(!Directory.Exists(runtime)||!Directory.GetDirectories(runtime,"8.*").Any()){state.Text=english?"Installing Microsoft .NET Desktop Runtime…":"正在安装微软 .NET 桌面运行时…";var start=new ProcessStartInfo(Path.Combine(source,"prerequisites","windowsdesktop-runtime-8.0.29-win-x64.exe"),"/install /passive /norestart"){UseShellExecute=true,Verb="runas"};using(var p=Process.Start(start)){await Task.Run(()=>p.WaitForExit());if(p.ExitCode!=0&&p.ExitCode!=3010)throw new IOException(english?"Runtime installation was not completed.":"运行时安装未完成。");}}string[] existing=ExistingFormats();string target=ChooseTarget(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"3DSTL"),existing.Length>0);state.Text=english?"Installing files…":"正在安装程序文件…";await Task.Run(()=>{foreach(string file in Directory.GetFiles(source,"*",SearchOption.AllDirectories)){string relative=file.Substring(source.Length);if(relative.StartsWith("prerequisites",StringComparison.OrdinalIgnoreCase))continue;string dest=Path.Combine(target,relative);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(file,dest,true);}});string exe=Path.Combine(target,"manager","3DSTL.exe");using(var p=Process.Start(new ProcessStartInfo(exe,existing.Length>0?"--register-only "+string.Join(" ",existing):"--repair 3mf stl obj ply off amf gcode gco step stp"){UseShellExecute=false,CreateNoWindow=true})){await Task.Run(()=>p.WaitForExit());if(p.ExitCode!=0)throw new IOException(english?"Association setup failed; open the manager and repair.":"缩略图注册未完成，请打开管理器点击修复。");}Type t=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(t);dynamic link=shell.CreateShortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"3DSTL.lnk"));link.TargetPath=exe;link.WorkingDirectory=target;link.IconLocation=exe+",0";link.Save();state.Text=english?"Installed. Desktop shortcut created.":"安装完成，桌面已建立3DSTL快捷方式。";Process.Start(new ProcessStartInfo(exe){UseShellExecute=false,CreateNoWindow=true});}catch(Exception e){state.Text=e.Message;}finally{install.Enabled=true;}};RefreshText();}
 void RefreshText(){install.Text=english?"Install / Repair":"安装 / 修复";info.Text=english?"Free model thumbnails for Windows File Explorer.\r\nAuthor: BA2IA · QQ: 21780 · Thanks to Codex\r\nOriginal source: MIT. Dependencies retain their licenses.\r\nInstalls for the current user; model files are not changed.":"免费模型缩略图，支持资源管理器和桌面。\r\n作者：BA2IA · QQ：21780 · 感谢 Codex\r\n原创源码采用 MIT；第三方组件保留各自许可。\r\n安装到当前用户目录，不修改模型文件。";}
 [STAThread]static void Main(string[] args){if(args.Length==1&&args[0]=="--selftest"){string home=Path.Combine(Path.GetTempPath(),"3DSTL-setup-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(home);try{if(ChooseTarget(home,false)!=Path.Combine(home,"App"))throw new Exception("Fresh install target is incorrect");Directory.CreateDirectory(Path.Combine(home,"App"));File.WriteAllText(Path.Combine(home,"App","keep.txt"),"old");string target=ChooseTarget(home,true);if(!target.StartsWith(Path.Combine(home,"Versions")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||File.ReadAllText(Path.Combine(home,"App","keep.txt"))!="old")throw new Exception("Upgrade must preserve the old installation");Console.WriteLine("PASS fresh install target and versioned upgrade preserving old files");}finally{Directory.Delete(home,true);}return;}Application.EnableVisualStyles();Application.Run(new Setup());}
}